<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Application;

use DateInterval;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Key\Domain\KeysManagerService;
use Civi\Lughauth\Features\Oidc\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\Oidc\User\Domain\Gateway\LoginGateway;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;

class AuthenticateUser
{
    public function __construct(
        private readonly LoginGateway $loginRepository,
        private readonly SessionStoreGateway $sessionStore,
        private readonly KeysManagerService $manager
    ) {
    }

    public function sessionAutenticated(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->fillPreLoadById($tenant, $request, $challenges),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce
        );
    }

    public function preAutenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->fillPreAuthenticated($tenant, $request, $challenges),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce
        );
    }

    public function autenticate(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $username,
        string $password,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->saveIt(
            $this->loginRepository->validatedUserData($tenant, $username, $password, $request),
            $request,
            $challenges,
            $issuer,
            $csid,
            $state,
            $nonce
        );
    }

    public function autenticateWithState(
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $tenant,
        string $username,
        string $password,
        string $issuer,
        string $csid,
        string $stateValue,
        string $nonce
    ): PublicLoginAuthResponse {
        return $this->autenticate($request, $challenges, $tenant, $username, $password, $issuer, $csid, $stateValue, $nonce);
    }

    private function saveIt(
        AuthenticationResult $validation,
        AuthenticationRequest $request,
        ChallengesState $challenges,
        string $issuer,
        string $csid,
        string $state,
        string $nonce
    ): PublicLoginAuthResponse {
        if (!$validation->valid) {
            throw new LoginException($validation, $validation->error);
        }
        $session = Uuid::uuid4()->toString();
        $authData = [
            'aud' => $this->tokenAudiences($request->client->id, $validation->audiences ?? []),
            'azp' => $request->client->id,
            'iss' => $issuer,
            'sub' => $validation->id,
            'name' => $validation->name ?? $validation->id,
            'email' => $validation->email ?? $validation->id,
            'tenant' => $validation->tenant,
            'tenant-name' => $validation->tenantName,
            'scope' => $validation->scope,
            'roles' => $validation->roles,
            'groups' => $validation->groups
        ];
        $idData = [
            'typ' => 'ID',
            'nonce' => $nonce,
            'session_state' => $session,
            's_hash' => self::generateHash($state),
        ];
        $sessionId = Uuid::uuid4()->toString();
        $sessionExpiration = new DateInterval("P15D");

        $this->sessionStore->saveSession($sessionId, $request->client, $issuer, $challenges, $validation, $csid, $sessionExpiration);

        return new PublicLoginAuthResponse(
            tenant: $validation->tenant,
            manager: $this->manager,
            authData: $authData,
            authExpiration: new DateInterval("PT10M"),
            idData: $idData,
            idExpiration: new DateInterval("PT10M"),
            sessionId: $sessionId,
            sessionExpiration: $sessionExpiration
        );
    }

    private function tokenAudiences(string $clientId, array $audiences): array
    {
        return array_values(array_unique([$clientId, ...$audiences ?? []]));
    }

    public static function generateHash(string $value): string
    {
        $hashedValue = hash('sha256', $value, true);
        $halfHashedValue = substr($hashedValue, 0, strlen($hashedValue) / 2);
        return rtrim(strtr(base64_encode($halfHashedValue), '+/', '-_'), '=');
    }
}
